  "starter": {
   "c": "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nint main(void) {\n    int n;\n    scanf(\"%d\", &n);\n    char tok[1000][16];\n    for (int i = 0; i < n; i++) scanf(\"%15s\", tok[i]);\n    // TODO: write your solution here\n    return 0;\n}\n",
   "cpp": "#include <iostream>\n#include <stack>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<string> tok(n);\n    for (auto &t : tok) cin >> t;\n    // TODO: write your solution here\n    return 0;\n}\n",
   "java": "import java.util.*;\n\nclass Main {\n    public static void main(String[] args) {\n        Scanner in = new Scanner(System.in);\n        int n = in.nextInt();\n        String[] tok = new String[n];\n        for (int i = 0; i < n; i++) tok[i] = in.next();\n        // TODO: write your solution here\n    }\n}\n",
   "py": "import sys\n\ndata = sys.stdin.read().split()\nn = int(data[0])\ntok = data[1:1 + n]\n# TODO: write your solution here\n"
  },
  "solution": {
   "c": "#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nint main(void) {\n    int n;\n    scanf(\"%d\", &n);\n    char tok[1000][16];\n    for (int i = 0; i < n; i++) scanf(\"%15s\", tok[i]);\n    long long st[1000];\n    int top = -1;\n    for (int i = 0; i < n; i++) {\n        char *t = tok[i];\n        if (strlen(t) == 1 && strchr(\"+-*/\", t[0])) {\n            long long b = st[top--], a = st[top--];\n            st[++top] = t[0] == '+' ? a + b : t[0] == '-' ? a - b : t[0] == '*' ? a * b : a / b;\n        } else st[++top] = atoll(t);\n    }\n    printf(\"%lld\\n\", st[top]);\n    return 0;\n}\n",
   "cpp": "#include <iostream>\n#include <stack>\n#include <string>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<string> tok(n);\n    for (auto &t : tok) cin >> t;\n    stack<long long> st;\n    for (const string &t : tok) {\n        if (t.size() == 1 && string(\"+-*/\").find(t[0]) != string::npos) {\n            long long b = st.top(); st.pop();\n            long long a = st.top(); st.pop();\n            st.push(t[0] == '+' ? a + b : t[0] == '-' ? a - b : t[0] == '*' ? a * b : a / b);\n        } else st.push(stoll(t));\n    }\n    cout << st.top() << \"\\n\";\n    return 0;\n}\n",
   "java": "import java.util.*;\n\nclass Main {\n    public static void main(String[] args) {\n        Scanner in = new Scanner(System.in);\n        int n = in.nextInt();\n        String[] tok = new String[n];\n        for (int i = 0; i < n; i++) tok[i] = in.next();\n        Deque<Long> st = new ArrayDeque<>();\n        for (String t : tok) {\n            if (t.length() == 1 && \"+-*/\".indexOf(t.charAt(0)) >= 0) {\n                long b = st.pop(), a = st.pop();\n                st.push(t.charAt(0) == '+' ? a + b : t.charAt(0) == '-' ? a - b : t.charAt(0) == '*' ? a * b : a / b);\n            } else st.push(Long.parseLong(t));\n        }\n        System.out.println(st.pop());\n    }\n}\n",
   "py": "import sys\n\ndata = sys.stdin.read().split()\nn = int(data[0])\ntok = data[1:1 + n]\nst = []\nfor t in tok:\n    if t in (\"+\", \"-\", \"*\", \"/\"):\n        b, a = st.pop(), st.pop()\n        if t == \"+\":\n            st.append(a + b)\n        elif t == \"-\":\n            st.append(a - b)\n        elif t == \"*\":\n            st.append(a * b)\n        else:\n            q = abs(a) // abs(b)                       # truncate toward zero\n            st.append(-q if (a < 0) != (b < 0) else q)\n    else:\n        st.append(int(t))\nprint(st.pop())\n"
  },
  "explain": "Scan the tokens left to right. A number is pushed. An operator pops the **right operand first, then the left operand**, applies itself and pushes the result. After the last token the single value on the stack is the answer. Take care with the order of the operands for − and /, and with truncation: C, C++ and Java already truncate toward zero; in Python use sign-aware division instead of //.",
