   "java": "import java.util.*;\n\nclass Main {\n    public static void main(String[] args) {\n        Scanner in = new Scanner(System.in);\n        int n = in.nextInt();\n        int[] a = new int[n];\n        for (int i = 0; i < n; i++) a[i] = in.nextInt();\n        int target = in.nextInt();\n        int low = 0, high = n - 1;\n        while (low <= high) {\n            int mid = low + (high - low) / 2;\n            if (a[mid] == target) { System.out.println(mid); return; }\n            if (a[low] <= a[mid]) {                     // left half is sorted\n                if (a[low] <= target && target < a[mid]) high = mid - 1;\n                else low = mid + 1;\n            } else {                                    // right half is sorted\n                if (a[mid] < target && target <= a[high]) low = mid + 1;\n                else high = mid - 1;\n            }\n        }\n        System.out.println(-1);\n    }\n}\n",
   "py": "import sys\n\ndata = sys.stdin.read().split()\nn = int(data[0])\na = list(map(int, data[1:1 + n]))\ntarget = int(data[1 + n])\nlow, high = 0, n - 1\nans = -1\nwhile low <= high:\n    mid = (low + high) // 2\n    if a[mid] == target:\n        ans = mid\n        break\n    if a[low] <= a[mid]:                        # left half is sorted\n        if a[low] <= target < a[mid]:\n            high = mid - 1\n        else:\n            low = mid + 1\n    else:                                       # right half is sorted\n        if a[mid] < target <= a[high]:\n            low = mid + 1\n        else:\n            high = mid - 1\nprint(ans)\n"
