   "cpp": "#include <algorithm>\n#include <iostream>\n#include <unordered_map>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<int> a(n);\n    for (int &x : a) cin >> x;\n    // TODO: write your solution here\n    return 0;\n}\n",
